WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_sl_summarize_feature'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '概括特征/现状', 'kp-sl-summarize-feature', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "归纳概括：特征与现状"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "描述一个事物长什么样，处于什么发展阶段。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、特征词提炼"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "特征词往往是非常简练的四字词语或短语。"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "如材料写：“这个行业有的企业赚钱，有的企业亏钱，产品五花八门，没有统一标准。”"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "提炼特征为：【发展不均衡】、【缺乏行业标准】。这是极度考验词汇积累量的题型。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、现状的双面性"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "如果让你概括某个行业的现状，一定要有全局观。现状 = 成绩（好的方面）+ 问题（坏的方面）。只答一面必然失掉一半的分数。"}]}]}$$ AS jsonb), NULL, '概括特征/现状的核心考点与高分作答技巧。', category_node.id, CAST('["申论", "归纳概括", "概括特征"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_sl_summarize_feature", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
